{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の hs",
      "detail": "stdにある「選挙権年齢と成年年齢」という重要なテーマや「いつ変わった？」という問いかけがhsで完全に抜け落ちており、単なるクイズのような文になっている。",
      "fix": "stdの意味に合わせて、「選挙権年齢も成年年齢も18歳になりました。それぞれいつ変わったのでしょうか。」などに直す。"
    },
    {
      "type": "名前と数字",
      "where": "summary の hs",
      "detail": "元文（std）の「平成27年」「平成28年」という元号が、hsでは「2015年」「2016年」と西暦に勝手に置き換えられている。",
      "fix": "「平成27年」「平成28年」の元号表記に統一する。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/3/text の hs",
      "detail": "stdは「18歳未満の者は選挙運動ができない」「18歳未満を使って選挙運動をしてはならない」という禁止規定に焦点を当てているが、hsは「18歳になると選挙運動ができる」という許可の側面を主にしており、後半も「18歳未満の人は選挙運動ができません」とあるものの、中身のニュアンスがずれている。また、stdにない「（特定の候補者への投票をよびかけること）」という解説が追加されている（ただし、これは分かりやすさの範囲とも言えるが、禁止事項の主旨と少しずれる）。",
      "fix": "stdに忠実に、18歳未満の選挙運動の禁止に焦点を当てる。"
    },
    {
      "type": "名前と数字",
      "where": "blocks/2/text の hs",
      "detail": "stdにある「公職選挙法第9条」の条文番号がhsでは完全に抜け落ちている。",
      "fix": "文末などに「（公職選挙法第9条）」の法律名と条数を補う。"
    },
    {
      "type": "名前と数字",
      "where": "blocks/5/text の hs",
      "detail": "stdにある「日本国憲法の改正手続に関する法律第3条」がhsでは完全に抜け落ちている。",
      "fix": "文末などに法律名と条数を補う。"
    }
  ]
}
